<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Models\InstallationEvent; use App\Services\{ActivationService,ApiResponse,LicenseStateService}; use Illuminate\Http\Request;
class HeartbeatController extends Controller { public function __invoke(Request $request,ActivationService $activation,LicenseStateService $states){$data=$request->validate(['hardware'=>'required|array','application_version'=>'nullable|string|max:50','agent_version'=>'nullable|string|max:50','health'=>'nullable|array']);$installation=$request->attributes->get('installation');try{$mismatch=$activation->verifyFingerprint($installation,$data['hardware'],$request->ip(),$request->attributes->get('request_id'));}catch(\InvalidArgumentException $e){return ApiResponse::error('LICENSE_INVALID',$e->getMessage(),422);}if($mismatch)return ApiResponse::error(...$mismatch);if($error=$states->validateInstallation($installation))return ApiResponse::error(...$error);$installation->update(['last_seen_at'=>now(),'last_ip'=>$request->ip(),'application_version'=>$data['application_version']??$installation->application_version,'agent_version'=>$data['agent_version']??$installation->agent_version,'health'=>$data['health']??$installation->health]);InstallationEvent::create(['installation_id'=>$installation->id,'type'=>'heartbeat_received','context'=>['health'=>$data['health']??null],'occurred_at'=>now()]);return ApiResponse::ok(['installation_id'=>$installation->uuid,'status'=>'active','server_timestamp'=>now()->timestamp,'target_release'=>$installation->target_release_id]);} }
